if (points.size() < 3) return 0;

    internal::K kernel;
    CGAL::Delaunay_triangulation_2<internal::K> dt;
    std::vector<internal::CGALPoint> cgal_points;
    cgal_points.reserve(points.size());
    for (const auto& p : points) {
        cgal_points.emplace_back(p.x(), p.y());
    }
    dt.insert(cgal_points.begin(), cgal_points.end());

    std::vector<CGAL::Face_handle> alpha_faces;
    for (auto fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
        internal::CGALPoint p1 = fit->vertex(0)->point();
        internal::CGALPoint p2 = fit->vertex(1)->point();
        internal::CGALPoint p3 = fit->vertex(2)->point();

        double a = std::sqrt(CGAL::a_dist_sq(p1, p2));
        double b = std::sqrt(CGAL::a_dist_sq(p2, p3));
        double c = std::sqrt(CGAL::a_dist_sq(p3, p1));
        double s = (a + b + c) / 2.0;
        double area = std::sqrt(s * (s - a) * (s - b) * (s - c));
        double radius = (a * b * c) / (4.0 * area);

        if (radius < alpha) {
            alpha_faces.push_back(fit);
        }
    }

    if (alpha_faces.empty()) return 0;

    std::vector<bool> visited(alpha_faces.size(), false);
    int components = 0;

    for (size_t i = 0; i < alpha_faces.size(); ++i) {
        if (!visited[i]) {
            components++;
            std::vector<size_t> queue;
            queue.push_back(i);
            visited[i] = true;
            size_t head = 0;
            while (head < queue.size()) {
                size_t curr_idx = queue[head++];
                CGAL::Face_handle curr_face = alpha_faces[curr_idx];
                for (int j = 0; j < 3; ++j) {
                    CGAL::Face_handle neighbor = curr_face->neighbor(j);
                    if (neighbor != nullptr && !neighbor->is_infinite()) {
                        for (size_t k = 0; k < alpha_faces.size(); ++k) {
                            if (!visited[k] && alpha_faces[k] == neighbor) {
                                visited[k] = true;
                                queue.push_back(k);
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    return components;

